#define MAX_STEPS 1000
#define MAX_DIST 1000.
#define SURF_DIST .01
#define saturate(x) clamp(x, 0.0, 1.0)
#define rcp(x) 1.0 / (x)
#define PI 3.14159265359

float dot2( in vec2 v ) { return dot(v,v); }// 二维向量模长
float dot2( in vec3 v ) { return dot(v,v); }// 三维向量模长
float ndot( in vec2 a, in vec2 b ) { return a.x * b.x - a.y * b.y; }
float Pow4( float x ) { float xx = x * x; return xx * xx; }
float Pow5( float x ) { return Pow4(x) * x; }

vec3 lerp( vec3 a, vec3 b, float c)
{
    float x = mix(a.x, b.x, c);
    float y = mix(a.y, b.y, c);
    float z = mix(a.z, b.z, c);
    return vec3(x, y, z);
}

/////////////////////SDF/////////////////////

float sdPlane(vec3 p) { return p.y; }

float dSphere(vec3 p, vec3 o, float radius) { return length(p - o.xyz) - radius; }

vec2 opUnion(vec2 d1, vec2 d2) {
    return d1.x < d2.x ? d1 : d2;
}

// 场景
vec2 GetDist(vec3 p)
{
    float planeDist = sdPlane(p);// ground

    // 遍历形式所有物体 物体摆放
    float sd = dSphere(p, vec3(0, 1, 3), 1.25);
    vec2 hit = opUnion(vec2(planeDist, 0), vec2(sd, 1));

    return hit;
}

vec2 RayMarch(vec3 ro, vec3 rd)
{
    float dO = 0.;
    float MaterialID = 0.0;

    for(int i = 0; i < MAX_STEPS; i++){
        vec3 p = ro + rd * dO;
        vec2 dS = GetDist(p);
        dO += dS.x;
        MaterialID = dS.y;
        if (dO > MAX_DIST || dS.x < SURF_DIST) break;     
    }

    return vec2(dO, MaterialID);
}

vec3 GetNormal(vec3 p)
{
    float d = GetDist(p).x;
    vec2 e = vec2(.01,0);

    vec3 n = d - vec3(
        GetDist(p - e.xyy).x,
        GetDist(p - e.yxy).x,
        GetDist(p - e.yyx).x);
    return normalize(n);
}

float GetLight(vec3 p, vec3 lightPos)
{
    vec3 l = normalize(lightPos - p);
    vec3 n = GetNormal(p);

    float dif = clamp(dot(n,l),0.,1.);
    float d = RayMarch(p + n * SURF_DIST * 2.,l).x;
    if(d < length(lightPos - p)) dif*=.1;

    return dif;
}

float GetShadow(vec3 P, vec3 LightPos)
{
    vec3 L = normalize(LightPos - P);
    vec3 N = GetNormal(P);

    float Shadow = 1.0;
    float Dist = RayMarch(P + N * SURF_DIST * 2., L).x;
    if(Dist < length(LightPos - P)) Shadow = 0.0;

    return Shadow;
}

/////////////////////BSDF/////////////////////

// GGX / Trowbridge-Reitz
// [Walter et al. 2007, "Microfacet models for refraction through rough surfaces"]
float D_GGX( float a2, float NoH )
{
	float d = ( NoH * a2 - NoH ) * NoH + 1.0;	// 2 mad
    return a2 / ( PI * d * d );					    // 4 mul, 1 rcp
}

// Appoximation of joint Smith term for GGX
// [Heitz 2014, "Understanding the Masking-Shadowing Function in Microfacet-Based BRDFs"]
float Vis_SmithJointApprox( float a2, float NoV, float NoL )
{
	float a = sqrt(a2);
	float Vis_SmithV = NoL * ( NoV * ( 1.0 - a ) + a );
	float Vis_SmithL = NoV * ( NoL * ( 1.0 - a ) + a );
	return 0.5 * rcp( Vis_SmithV + Vis_SmithL );
}

// [Schlick 1994, "An Inexpensive BRDF Model for Physically-Based Rendering"]
vec3 F_Schlick( vec3 SpecularColor, float VoH )
{
	float Fc = Pow5( 1.0 - VoH );				// 1 sub, 3 mul
	//return Fc + (1 - Fc) * SpecularColor;		  // 1 add, 3 mad

	// Anything less than 2% is physically impossible and is instead considered to be shadowing
	return saturate( 50.0 * SpecularColor.y ) * Fc + (1.0 - Fc) * SpecularColor;
}

float DielectricSpecularToF0(float Specular)
{
	return 0.08f * Specular;
}

vec3 ComputeF0(float Specular, vec3 BaseColor, float Metallic)
{
	return lerp(vec3(DielectricSpecularToF0(Specular)), BaseColor, Metallic);
}


/////////////////////Tone mapping and transfer functions/////////////////////

vec3 Tonemap_ACES(const vec3 x)
{
    // Narkowicz 2015, "ACES Filmic Tone Mapping Curve"
    const float a = 2.51;
    const float b = 0.03;
    const float c = 2.43;
    const float d = 0.59;
    const float e = 0.14;
    return (x * (a * x + b)) / (x * (c * x + d) + e);
}

vec3 OECF_sRGBFast(const vec3 linear)
{
    return pow(linear, vec3(1.0 / 2.2));
}

/////////////////////Main/////////////////////

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // User Control
    vec3 BaseColor = vec3(1.0, 1.0, 1.0);
    float Specular = 0.9f;
    float Roughness = 0.9f;
    float Metalic = 0.9f;

    vec3 Ray0 = vec3(0, 3, 0);// CameraPos
    vec3 LightPos = vec3(0, 3, 1);
    //LightPos.xz += vec2(sin(iTime), cos(iTime)) * 2.;
    LightPos.x += sin(iTime) * 2.5;// Time varying pixel color

    // Normalized pixel coordinates (from 0 to 1)
    vec2 UV = (fragCoord - .5 * iResolution.xy) / iResolution.y;

    // RayTracing
    vec3 RayDir = normalize(vec3(UV.x, UV.y -.3, .35));// cameraDir
    vec2 Dist = RayMarch(Ray0, RayDir);   
    vec3 Pos = Ray0 + RayDir * Dist.x;

    // BSDF
    vec3 N = GetNormal(Pos);
    vec3 V = normalize(Ray0 - Pos);
    vec3 L = normalize(LightPos - Pos);
    vec3 H = normalize(L + V);

    float NoV = abs(dot(N, V)) + 1e-5;
    float NoL = saturate(dot(N, L));
    float NoH = saturate(dot(N, H));
    float LoH = saturate(dot(L, H));
    float VoH = saturate(dot(V, H));

    float a2 = Pow4(Roughness);

    float D = D_GGX(a2, NoH);

    float G = Vis_SmithJointApprox(a2, NoV, NoL);

    // Diffuse
    vec3 DiffuseColor = BaseColor - BaseColor * Metalic;
    vec3 LightingDiffuse = DiffuseColor * (1.0 / PI);// Diffuse_Lambert

    // Specular
    vec3 SpecularColor = ComputeF0(Specular, BaseColor, Metalic);
    vec3 F = F_Schlick(SpecularColor, VoH);

    vec3 LightingSpecular = vec3(G);//D * G * F;

    vec3 FinalColor = LightingSpecular;// + LightingDiffuse;

    float MaterialID = Dist.y;
    if (MaterialID < 1.0)
        FinalColor = vec3(0.3);

    // Shadow
    float Shadow = GetShadow(Pos, LightPos);
    FinalColor *= Shadow;

    // Tone mapping
    FinalColor = Tonemap_ACES(FinalColor);

    // Exponential distance fog
    //color = mix(color, 0.8 * vec3(0.7, 0.8, 1.0), 1.0 - exp2(-0.011 * distance * distance));

    // Gamma compression
    FinalColor = OECF_sRGBFast(FinalColor);

    // Output to screen
    fragColor = vec4(FinalColor, 1.0);
}
